document.addEventListener('click',event=>{const filter=event.target.closest('[data-task-manager-filter]');if(filter){taskManagerState.filter=filter.dataset.taskManagerFilter;render();return;}const button=event.target.closest('[data-task-manager-action]');if(!button)return;const action=button.dataset.taskManagerAction,id=button.dataset.id;if(action==='open-prospect'){selectedLeadId=button.dataset.leadId;setView('leadDetail');return;}if(action==='new-task'){opsTaskFormAdmin();return;}if(button.disabled)return;const task=state.tasks.find(item=>item.id===id);if(action==='complete'&&task){task.done=!task.done;save('Task status');render();toast(task.done?'Task completed.':'Task reopened.');}if(action==='edit'&&task){opsTaskFormAdmin(id);}if(action==='delete'&&task&&confirm(`Delete “${task.title}”?`)){const snapshot=JSON.stringify(state);task.deleted=true;if(!adminPersistChanges('Task removed',snapshot))return;render();toast('Task deleted.');}},true);
