/* Board view: the task manager uses the same visual rhythm as the prospect pipeline. */
function renderTaskBoard(){
 adminEnsureData();const all=taskManagerRows(),rows=taskManagerRowsFiltered(),open=all.filter(row=>!row.done),members=adminActiveMembers(),laneDefs=[['overdue','Overdue','Past due'],['today','Today','Due today'],['upcoming','Upcoming','Next 7 days'],['completed','Completed','Finished']];
 const counts=member=>all.filter(row=>(member==='all'||row.assigneeId===member||row.owner===adminMember(member)?.name)&&!row.done).length;
 const ownerChips=[`<button type="button" class="task-owner-chip ${taskManagerState.assignee==='all'?'active':''}" data-task-manager-owner="all"><span class="admin-member-avatar">ALL</span><span><strong>All assigned</strong><small>${open.length} open tasks</small></span></button>`,...members.map(member=>`<button type="button" class="task-owner-chip ${taskManagerState.assignee===member.id?'active':''}" data-task-manager-owner="${member.id}"><span class="admin-member-avatar">${esc(initials(member.name))}</span><span><strong>${esc(member.name)}</strong><small>${counts(member.id)} open tasks</small></span></button>`)].join('');
 const laneRows=(key)=>rows.filter(row=>taskManagerBucket(row)===key);const board=laneDefs.map(([key,label,sub])=>{const items=laneRows(key);return `<section class="task-board-lane ${key}"><header><div><span class="task-lane-dot"></span><strong>${label}</strong><small>${sub}</small></div><b>${items.length}</b></header><div class="task-lane-body">${items.map(row=>`<article class="task-board-card ${row.done?'is-done':''}"><div class="task-board-card-top"><span>${esc(row.type)}</span>${tag(row.priority)}</div><h3>${esc(row.title)}</h3><p>${esc(row.description||row.module||'No details added yet.')}</p><div class="task-board-card-client"><strong>${esc(row.clientName)}</strong><small>${esc(row.module)}</small></div><div class="task-board-card-foot"><span class="task-board-assignee"><span class="admin-member-avatar">${esc(initials(row.owner))}</span>${esc(row.owner)}</span><span class="task-board-due">${row.done?'Completed':row.due?prettyDate(row.due):'No date'}</span></div><div class="task-board-card-actions">${row.virtual?taskManagerAction('open-prospect',row,false):`${taskManagerAction('complete',row,false)}${taskManagerAction('edit',row,false)}${taskManagerAction('delete',row,false)}`}</div></article>`).join('')||'<p class="task-lane-empty">No tasks here</p>'}</div></section>`;}).join('');
 return `<div class="task-board-page"><header class="task-board-header"><div><span class="followup-eyebrow">WORK MANAGEMENT</span><h1>Task manager</h1><p>Plan every follow-up, client task and internal handoff in one place.</p></div><div class="task-board-header-actions"><label class="task-assigned-select"><span>SHOW TASKS FOR</span><select data-task-manager-change="assignee" aria-label="Show tasks for">${opsOption('all','All assigned tasks',taskManagerState.assignee)}${members.map(member=>opsOption(member.id,member.name,taskManagerState.assignee)).join('')}</select></label><button class="btn btn-primary" type="button" data-task-manager-action="new-task">${icon('plus')}New task</button></div></header><section class="task-owner-strip"><span class="task-owner-label">Team view</span>${ownerChips}</section><nav class="followup-tabs task-board-tabs" aria-label="Task views">${[['all','All tasks'],['overdue','Overdue'],['today','Today'],['upcoming','Upcoming'],['completed','Completed']].map(([key,label])=>`<button type="button" class="${taskManagerState.filter===key?'active':''}" data-task-manager-filter="${key}">${label}${key==='all'?`<span>${open.length}</span>`:''}</button>`).join('')}</nav><div class="task-board-summary"><span><strong>${rows.length}</strong> ${taskManagerState.filter==='all'?'tasks in this workspace':`${taskManagerState.filter} tasks`}</span><span>Drag-style board view · click a card action to update</span></div><main class="task-board-grid">${board}</main></div>`;
}
renderTasks=renderTaskBoard;renderTasksAdmin=renderTaskBoard;adminRenderTasks=renderTaskBoard;
document.addEventListener('click',event=>{const owner=event.target.closest('[data-task-manager-owner]');if(owner){taskManagerState.assignee=owner.dataset.taskManagerOwner;render();$('[data-task-manager-owner="'+taskManagerState.assignee+'"]')?.focus();}},true);

/* Compact board pass: team view is the primary navigation; status counts stay on the lanes. */
function renderTaskBoardCompact(){
 adminEnsureData();taskManagerState.filter='all';const all=taskManagerRows(),rows=taskManagerRowsFiltered(),open=all.filter(row=>!row.done),members=adminActiveMembers();
 const counts=member=>all.filter(row=>(member==='all'||row.assigneeId===member||row.owner===adminMember(member)?.name)&&!row.done).length;
 const ownerChips=[`<button type="button" class="task-team-card ${taskManagerState.assignee==='all'?'active':''}" data-task-manager-owner="all"><span class="task-team-avatar task-team-all">ALL</span><span class="task-team-copy"><strong>All assigned</strong><small>${open.length} open tasks</small></span><i class="task-team-spark">✦</i></button>`,...members.map((member,index)=>`<button type="button" class="task-team-card ${taskManagerState.assignee===member.id?'active':''}" data-task-manager-owner="${member.id}"><span class="task-team-avatar tone-${index%4}">${esc(initials(member.name))}</span><span class="task-team-copy"><strong>${esc(member.name)}</strong><small>${counts(member.id)} open tasks</small></span><i class="task-team-presence"></i></button>`)].join('');
 const laneDefs=[['overdue','Overdue','Past due'],['today','Today','Due today'],['upcoming','Upcoming','Next 7 days'],['completed','Completed','Finished']];
 const card=row=>`<article class="task-board-card ${row.done?'is-done':''}"><div class="task-board-card-top"><span>${esc(row.type)}</span>${tag(row.priority)}</div><h3>${esc(row.title)}</h3><p>${esc(row.description||row.module||'No details added yet.')}</p><div class="task-board-card-client"><strong>${esc(row.clientName)}</strong><small>${esc(row.module)}</small></div><div class="task-board-card-foot"><span class="task-board-assignee"><span class="task-team-avatar mini">${esc(initials(row.owner))}</span>${esc(row.owner)}</span><span class="task-board-due">${row.done?'Completed':row.due?prettyDate(row.due):'No date'}</span></div><div class="task-board-card-actions">${row.virtual?taskManagerAction('open-prospect',row,false):`${taskManagerAction('complete',row,false)}${taskManagerAction('edit',row,false)}${taskManagerAction('delete',row,false)}`}</div></article>`;
 const board=laneDefs.map(([key,label,sub])=>{const items=rows.filter(row=>taskManagerBucket(row)===key);return `<section class="task-board-lane ${key}"><header><div><span class="task-lane-dot"></span><strong>${label}</strong><small>${sub}</small></div><b>${items.length}</b></header><div class="task-lane-body">${items.map(card).join('')||'<p class="task-lane-empty">No tasks here</p>'}</div></section>`}).join('');
 return `<div class="task-board-page task-board-compact"><header class="task-board-header"><div><span class="followup-eyebrow">WORK MANAGEMENT</span><h1>Task manager</h1><p>Plan every follow-up, client task and internal handoff in one place.</p></div><div class="task-board-header-actions"><label class="task-assigned-select"><span>SHOW TASKS FOR</span><select data-task-manager-change="assignee" aria-label="Show tasks for">${opsOption('all','All assigned tasks',taskManagerState.assignee)}${members.map(member=>opsOption(member.id,member.name,taskManagerState.assignee)).join('')}</select></label><button class="btn btn-primary" type="button" data-task-manager-action="new-task">${icon('plus')}New task</button></div></header><section class="task-team-view"><div class="task-team-view-heading"><span>TEAM VIEW</span><small>${open.length} open tasks across ${members.length} members</small></div><div class="task-team-cards">${ownerChips}</div></section><div class="task-board-summary compact-summary"><span><strong>${rows.length}</strong> tasks in this workspace</span><span>Choose a team member to focus the board</span></div><main class="task-board-grid">${board}</main></div>`;
}
renderTasks=renderTaskBoardCompact;renderTasksAdmin=renderTaskBoardCompact;adminRenderTasks=renderTaskBoardCompact;

/* Final task manager pass: compact prospect-style spacing, visible stats, and persona avatars. */
function renderTaskBoardRefined(){
 adminEnsureData();const all=taskManagerRows(),rows=taskManagerRowsFiltered(),open=all.filter(r=>!r.done);
 const members=state.teamMembers.filter(m=>m.status!=='Inactive'||all.some(r=>r.assigneeId===m.id)),unassigned=all.some(r=>!adminMember(r.assigneeId));
 const people=[{id:'all',name:'All tasks'},...members,...(unassigned?[{id:'unassigned',name:'Unassigned'}]:[])];
 const counts=id=>open.filter(r=>id==='all'||(id==='unassigned'?!adminMember(r.assigneeId):r.assigneeId===id)).length;
 const ownerChips=people.map(m=>'<button type="button" class="task-team-card '+(taskManagerState.assignee===m.id?'active':'')+'" data-task-manager-owner="'+esc(m.id)+'" aria-pressed="'+(taskManagerState.assignee===m.id)+'">'+(m.id==='all'?'<span class="task-team-all-icon" aria-hidden="true">'+icon('users')+'</span>':adminMemberAvatar(m))+'<span class="task-team-copy"><strong>'+esc(m.name)+'</strong><small>'+counts(m.id)+' open'+(m.status==='Inactive'?' · Inactive':' tasks')+'</small></span></button>').join('');
 const lanes=[['overdue','Overdue','Past due'],['today','Today','Due today'],['upcoming','Upcoming','Next 7 days'],['later','Later','After 7 days · No date'],['completed','Completed','Finished work']];
 const card=row=>'<article class="task-board-card '+(row.done?'is-done':'')+'"><div class="task-board-card-top"><span>'+esc(row.type)+'</span>'+tag(row.priority)+'</div>'+
 '<h3><button type="button" data-task-manager-action="'+(row.virtual?'open-prospect':'edit')+'" data-id="'+esc(row.id)+'" '+(row.virtual?'data-lead-id="'+esc(row.leadId)+'"':'')+'>'+esc(row.title)+'</button></h3>'+
 (row.description?'<p>'+esc(row.description)+'</p>':'')+
 '<div class="task-board-card-client"><strong>'+esc(row.clientName)+'</strong>'+(row.module&&row.module!=='General workspace'?'<small>'+esc(row.module)+'</small>':'')+'</div>'+
 '<div class="task-board-card-foot"><span class="task-board-assignee">'+adminMemberAvatar(adminMember(row.assigneeId))+'<span>'+esc(row.owner)+'</span></span></div>'+
 '<div class="task-board-card-actions"><span class="task-board-due">'+icon(row.done?'check':'calendar')+(row.done?'Completed':row.due?prettyDate(row.due):'No date')+'</span>'+
 (row.virtual?taskManagerAction('open-prospect',row,false):renderRecordRowActions('task',row.id,row.title))+'</div></article>';
 const board=lanes.map(([key,label,sub])=>{const items=rows.filter(row=>taskManagerBucket(row)===key);return '<section class="task-board-lane '+key+'" aria-label="'+label+' tasks"><header><div><span class="task-lane-dot"></span><strong>'+label+'</strong><small>'+sub+'</small></div><b>'+items.length+'</b></header><div class="task-lane-body" tabindex="0" role="region" aria-label="'+label+' task list">'+(items.map(card).join('')||'<p class="task-lane-empty">No '+label.toLowerCase()+' tasks</p>')+'</div></section>';}).join('');
 const filtered=taskManagerState.filter!=='all'||taskManagerState.assignee!=='all'||taskManagerState.query||taskManagerState.type!=='all'||taskManagerState.client!=='all';
 return '<div class="task-board-page task-board-compact task-board-refined"><header class="task-board-header"><div><span class="followup-eyebrow">WORK MANAGEMENT</span><h1>Task manager</h1><p>Follow-ups, client work and team assignments in one place.</p></div><button class="btn btn-primary" type="button" data-task-manager-action="new-task">'+icon('plus')+'New task</button></header>'+
 '<section class="task-team-view" aria-label="Filter by team member"><div class="task-team-view-heading"><span>TEAM VIEW</span><small>'+open.length+' open · '+all.filter(r=>r.done).length+' completed</small></div><div class="task-team-cards">'+ownerChips+'</div></section>'+
 '<div class="task-board-toolbar"><label class="task-board-search">'+icon('search')+'<input type="search" data-task-manager-input="query" aria-label="Search tasks" placeholder="Search tasks, clients or workstreams" value="'+esc(taskManagerState.query)+'"></label>'+
 '<select data-task-manager-change="filter" aria-label="Task status">'+[['all','All tasks'],['open','Open tasks'],...lanes.map(([k,l])=>[k,l])].map(([k,l])=>opsOption(k,l,taskManagerState.filter)).join('')+'</select>'+
 '<select data-task-manager-change="sort" aria-label="Sort tasks">'+[['due','Due date'],['priority','Priority'],['recent','Recently added']].map(([k,l])=>opsOption(k,l,taskManagerState.sort)).join('')+'</select>'+
 (filtered?'<button class="btn" type="button" data-task-clear>Clear filters</button>':'')+'</div>'+
 (!rows.length?'<div class="task-board-no-results" role="status"><strong>'+(filtered?'No tasks match these filters.':'No tasks yet.')+'</strong><span>'+(filtered?'Clear filters to see all work.':'Create a task to start assigning work.')+'</span></div>':'')+
 '<div class="task-board-grid" role="region" aria-label="Task board. Scroll horizontally for more columns." tabindex="0">'+board+'</div></div>';
}
renderTasks=renderTaskBoardRefined;renderTasksAdmin=renderTaskBoardRefined;adminRenderTasks=renderTaskBoardRefined;


document.addEventListener('click',event=>{
 const link=event.target.closest('[data-view="tasks"]');
 if(link)taskManagerState={filter:link.dataset.taskScope||'all',assignee:link.dataset.taskOwner||'all',query:'',client:'all',type:'all',sort:'due'};
 if(event.target.closest('[data-task-clear]')){taskManagerState={filter:'all',assignee:'all',query:'',client:'all',type:'all',sort:'due'};render();}
},true);


document.addEventListener('click',event=>{
 const tab=event.target.closest('[data-access-tab]');
 if(tab){accessState.tab=tab.dataset.accessTab==='roles'?'roles':'users';render();$('[data-access-tab="'+accessState.tab+'"]')?.focus();return;}
 const page=event.target.closest('[data-access-page]');
 if(page){accessState.page=Number(page.dataset.accessPage)||1;render();return;}
 const select=event.target.closest('[data-access-select]');
 if(select){$('#admin-role-form')?.querySelectorAll('input[name="permissions"]').forEach(input=>{input.checked=select.dataset.accessSelect==='all';});accessUpdatePermissionSummary();return;}
 const button=event.target.closest('[data-access-action]');if(!button)return;const action=button.dataset.accessAction,id=button.dataset.id;
 if(action==='show-role'||action==='select-role'){if(!adminRole(id)){toast('This role is no longer available.');return;}accessState.selectedRole=id;accessState.tab='roles';render();if(action==='select-role')$('[data-access-action="select-role"][data-id="'+id+'"]')?.focus();}
 if(action==='role-users'){accessState={...accessState,tab:'users',role:id,status:'all',query:'',page:1};accessEditBaseline=undefined;$('#modal-root').innerHTML='';render();}
 if(action==='clear-filters'){accessState={...accessState,role:'all',status:'all',query:'',page:1};render();$('[data-access-input="users"]')?.focus();}
 if(action==='history')accessShowHistory();
 if(action==='confirm-status')accessConfirmStatus(id,button.dataset.status);
 if(action==='confirm-delete-role')accessConfirmDeleteRole(id);
},true);
document.addEventListener('input',event=>{
 if(event.target.dataset.accessInput!=='users')return;
 const cursor=event.target.selectionStart;accessState.query=event.target.value;accessState.page=1;render();
 const input=$('[data-access-input="users"]');input?.focus();input?.setSelectionRange(cursor,cursor);
},true);
document.addEventListener('change',event=>{
 const key=event.target.dataset.accessFilter;
 if(key==='role'||key==='status'){accessState[key]=event.target.value;accessState.page=1;render();$('[data-access-filter="'+key+'"]')?.focus();return;}
 if(event.target.id==='admin-member-role'||event.target.id==='admin-member-status'){
  const preview=$('#access-user-preview');if(preview)preview.innerHTML=accessMemberPreview($('#admin-member-role').value,$('#admin-member-status').value);
 }
 if(event.target.name==='permissions'&&event.target.closest('#admin-role-form'))accessUpdatePermissionSummary();
},true);

document.addEventListener('DOMContentLoaded',accessSyncCurrentUser);
